controls.attribute:
description={rangeSuccessRate === null
            ? '没有请求，不能推断成功率'
            : `${formatNumber(summary.totalRequests - summary.successRequests)} 次异常`}

description={canManage
          ? '管理上游接入、凭证账号、模型目录、别名和默认路由'
          : '查看组织当前的模型、稳定别名和协议能力；此页面不提供任何配置写操作'}

title={providers.length === 0
                            ? canManage ? '尚未配置 Provider' : '当前没有可访问模型'
                            : '没有匹配的模型'}

description={rotationResult
          ? '待启用密钥尚未完成交接。留在此页是默认选项；确认离开时会先放弃待启用密钥，旧密钥继续有效。'
          : '密钥创建或轮换请求仍在进行，或完整新密钥尚未确认保存。离开后可能永久无法再查看它；默认应留在此页。'}

description={quotaToDelete
          ? `将移除其${periodLabels[quotaToDelete.period]}${quotaTypeLabels[quotaToDelete.quotaType]}限制；删除后该类型不再受这条规则约束。历史用量不会删除。`
          : ''}

description={data.dualApprovalRequired
          ? '高风险变更必须先形成载荷摘要，再由另一名管理员审批；Dashboard 与 API 共用同一门禁。'
          : '免费小团队模式允许管理员直接执行并保留审计；需要复核时仍可使用完整的双人审批流程。'}

types.declaration:
export interface EnterpriseRequestPage {
  requests: EnterpriseRequest[]
  total: number
  page: number
  pageSize: number
}

export interface EnterpriseRequestDetail {
  request: EnterpriseRequest
  attempts: EnterpriseAttempt[]
}

export interface EnterpriseBudgetScope {
  organizationId: string
  projectId: string
  environmentId: string
}

export interface EnterpriseBudgetView {
  account: EnterpriseBudgetAccount
  recentEvents: EnterpriseBudgetEvent[]
}

export interface EnterpriseBudgetUpdate extends EnterpriseBudgetScope {
  limitMicrounits?: number
  unlimited: boolean
}

export interface EnterpriseBudgetAdjustment extends EnterpriseBudgetScope {
  deltaMicrounits: number
  reason: string
  evidenceReference: string
}

export interface ChangeApproval {
  actorId: string
  actorName: string
  approvedAtMs: number
}

export interface GovernanceChangeInput {
  action: string
  target: string
  payload: unknown
  reason: string
}

export interface ModelPricingRates {
  inputPerMillion: number
  outputPerMillion: number
  cacheWritePerMillion: number
  cacheReadPerMillion: number
}

export interface ProviderRetryPolicy {
  max_attempts: number
  initial_delay_ms: number
  max_delay_ms: number
  jitter_ratio: number
}

export interface ModelPricing {
  inputPerMillion: number
  outputPerMillion: number
  cacheWritePerMillion: number
  cacheReadPerMillion: number
}

export interface ProviderBalanceInfo {
  currency: 'CNY' | 'USD'
  totalBalance: string
  grantedBalance: string
  toppedUpBalance: string
}

export interface ModelAlias {
  alias: string
  target: string
  resolvedProvider: string
  resolvedModel: string
}

export interface OpsIncidentEvidence {
  id: string
  incidentId: string
  observedAtMs: number
  evidence: Record<string, unknown>
}

export interface OpsIncidentDetail extends OpsIncidentSummary {
  evidence: OpsIncidentEvidence[]
  timeline: OpsIncidentTimelineEntry[]
}

export interface OpsAgentConfigurationInput {
  enabled: boolean
  analysisEnabled: boolean
  selectedModel: string | null
  preferLocal: boolean
}

export interface OpsIncidentStatusInput {
  status: Exclude<OpsIncidentStatus, 'open' | 'resolved'>
  reason: string
}

export interface OpsIncidentFeedbackInput {
  outcome: 'true_positive' | 'false_positive' | 'needs_review'
  rootCauseCorrect?: boolean
  recommendationAdopted?: boolean
  note?: string
}

export interface TimeSeriesPoint {
  timestamp: string
  value: number
  label?: string
}

export interface ServerSettings {
  bindAddress: string
  maxRequestBodyBytes: number
  maxConcurrentRequests: number
}

export interface AuthSettings {
  enabled: boolean
  tokenEnvVar: string
  allowNoAuth: boolean
}

export interface GatewaySettings {
  defaultProvider: string
  providerOrder: string[]
}

export interface RateLimitSettings {
  maxConcurrentRequests: number
  maxRequestBodyBytes: number
  requestTimeoutSecs: number
  streamIdleTimeoutSecs: number
}

export interface SetupStatus {
  ready: boolean
  activeProviderCount: number
  defaultProviderReady: boolean
  checks: SetupCheck[]
  issues: Array<{
    severity: 'error' | 'warning'
    message: string
  }>
}

export interface SetupCheck {
  id: string
  label: string
  status: 'ok' | 'warning' | 'error'
  detail: string
}

export interface ConfigReloadResult {
  ok: boolean
  settings: SystemSettings
  providerCount: number
  defaultProvider: string
  providerOrder: string[]
  issues: Array<{
    severity: 'error' | 'warning'
    message: string
  }>
  reloadScope?: {
    applied: string[]
    requiresRestart: string[]
  }
}

export interface AuditEventsResponse {
  events: AuditEvent[]
  total: number
}

export interface UpdateUserInput {
  email?: string
  password?: string
  role?: UserRole
  status?: User['status']
}
